from typing import List

def literal_sequence(length: int) -> List[int]:
    """Generate the least-positive singleton-sum-avoidance trajectory."""
    if length < 0:
        raise ValueError("length must be nonnegative")
    if length == 0:
        return []
    values = [1] if length == 1 else [1, 1]
    while len(values) < length:
        forbidden = values[-2] + values[-1]
        candidate = 1
        while candidate == forbidden:
            candidate += 1
        values.append(candidate)
    return values

if __name__ == "__main__":
    values = literal_sequence(20)
    print(values)
    assert values == [1] * 20

from fractions import Fraction
from typing import List

def displayed_sequence(length: int) -> List[int]:
    if length < 0:
        raise ValueError("length must be nonnegative")
    out: List[int] = []
    value = 1
    for n in range(length):
        out.append(value)
        value += n
    return out

def displayed_closed(n: int) -> int:
    if n < 0:
        raise ValueError("n must be nonnegative")
    return 1 + n * (n - 1) // 2

if __name__ == "__main__":
    values = displayed_sequence(12)
    print(values)
    assert all(v == displayed_closed(n) for n, v in enumerate(values))
    for n in (10, 100, 1000, 1_000_000):
        ratio = Fraction(displayed_closed(n), n*n)
        print(n, float(ratio))

from dataclasses import dataclass

@dataclass(frozen=True)
class Witness:
    bound: int
    index: int
    discrepancy: int

def displayed(n: int) -> int:
    return 1 + n * (n - 1) // 2

def quarter_square(n: int) -> int:
    return n * n // 4

def construct_witness(bound: int) -> Witness:
    if bound < 0:
        raise ValueError("bound must be nonnegative")
    k = bound + 2
    n = 2 * k
    gap = displayed(n) - quarter_square(n)
    assert gap == k * (k - 1) + 1 and gap > bound
    return Witness(bound, n, gap)

if __name__ == "__main__":
    for c in (0, 1, 10, 100, 10_000):
        print(construct_witness(c))

